private void button4_Click(object sender, EventArgs e)
{
    string FishHome = @"C:\AI\fish-speech";
    string ResultsHome = Path.Combine(FishHome, "results");
    string RecentModelFolder = PrintMostRecentFolderName(ResultsHome);

    // Validate that we actually found a recent model folder
    if (string.IsNullOrEmpty(RecentModelFolder))
    {
        MessageBox.Show("No recent model folder found in results directory.", 
                       "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
        return;
    }

    string Checkpoints = Path.Combine(ResultsHome, RecentModelFolder, "checkpoints");

    // Check if ResultList has a selected item
    if (ResultList.SelectedItem == null)
    {
        MessageBox.Show("Please select a result from the list first.", 
                       "Warning", MessageBoxButtons.OK, MessageBoxIcon.Warning);
        return;
    }

    // Check if checkpoints directory exists
    if (!Directory.Exists(Checkpoints))
    {
        DialogResult createDir = MessageBox.Show(
            $"Checkpoints directory doesn't exist yet at:\n{Checkpoints}\n\nCreate it and continue?", 
            "Directory Missing", MessageBoxButtons.YesNo, MessageBoxIcon.Question);

        if (createDir == DialogResult.Yes)
        {
            try
            {
                Directory.CreateDirectory(Checkpoints);
            }
            catch (Exception ex)
            {
                MessageBox.Show($"Failed to create directory: {ex.Message}", 
                               "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                return;
            }
        }
        else
        {
            return;
        }
    }

    // Check for existing checkpoints and warn about override
    try
    {
        string mostRecentCheckpoint = PrintMostRecentFolderName(Checkpoints);

        if (!string.IsNullOrEmpty(mostRecentCheckpoint))
        {
            string fullCheckpointPath = Path.Combine(Checkpoints, mostRecentCheckpoint);

            DialogResult result = MessageBox.Show(
                $"Found existing checkpoint at:\n{fullCheckpointPath}\n\n" +
                $"Do you want to override it with the new merge?", 
                "Override Existing Checkpoint", 
                MessageBoxButtons.YesNo, 
                MessageBoxIcon.Warning);

            if (result == DialogResult.No)
            {
                return;
            }
        }
    }
    catch (Exception ex)
    {
        MessageBox.Show($"Error checking for existing checkpoints: {ex.Message}", 
                       "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
        return;
    }

    // Finally, proceed with the merge
    try
    {
        MergeLora("fish-speech", RecentModelFolder, ResultList.SelectedItem.ToString(), FishHome);
        MessageBox.Show("Merge completed successfully!", "Success", 
                       MessageBoxButtons.OK, MessageBoxIcon.Information);
    }
    catch (Exception ex)
    {
        MessageBox.Show($"Merge failed: {ex.Message}", "Error", 
                       MessageBoxButtons.OK, MessageBoxIcon.Error);
    }
}
```

